package app.devlens;
import android.app.*;import android.content.*;import android.os.*;import android.media.*;import android.media.session.*;import android.net.Uri;import org.json.*;
public class MusicService extends Service{
 MediaPlayer player;MediaSession session;JSONArray queue=new JSONArray();static volatile int queueIndex=-1;String title="DevLens Music";static volatile String state="stopped",track="",error="";static volatile int position=0,duration=0;Handler handler=new Handler();
 static JSONObject status()throws Exception{return new JSONObject().put("state",state).put("title",track).put("error",error).put("position",position).put("duration",duration).put("index",queueIndex);}
 @Override public void onCreate(){super.onCreate();NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("music","Музыка",NotificationManager.IMPORTANCE_LOW));session=new MediaSession(this,"DevLens");session.setCallback(new MediaSession.Callback(){@Override public void onPlay(){resume();}@Override public void onPause(){pause();}@Override public void onSkipToNext(){advance(1);}@Override public void onSkipToPrevious(){advance(-1);}@Override public void onSeekTo(long p){if(player!=null){player.seekTo((int)p);update();}}});session.setActive(true);handler.post(new Runnable(){public void run(){if(player!=null&&("playing".equals(state)||"paused".equals(state)))try{position=player.getCurrentPosition();duration=player.getDuration();}catch(Exception ignored){}handler.postDelayed(this,1000);}});registerReceiver(noisy,new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY));}
 BroadcastReceiver noisy=new BroadcastReceiver(){public void onReceive(Context c,Intent i){pause();}};
 AudioFocusRequest focus;
 boolean gainFocus(){AudioManager am=(AudioManager)getSystemService(AUDIO_SERVICE);if(focus==null)focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()).setOnAudioFocusChangeListener(f->{if(f<0)pause();}).build();return am.requestAudioFocus(focus)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED;}
 @Override public int onStartCommand(Intent i,int flags,int id){startForeground(42,notification());if(i==null){stopSelf();return START_NOT_STICKY;}String action=i.getAction();if("pause".equals(action)){pause();return START_NOT_STICKY;}if("resume".equals(action)){resume();return START_NOT_STICKY;}if("stop".equals(action)){stopSelf();return START_NOT_STICKY;}if("next".equals(action)){advance(1);return START_NOT_STICKY;}if("previous".equals(action)){advance(-1);return START_NOT_STICKY;}try{if(i.hasExtra("queue")){queue=new JSONArray(i.getStringExtra("queue"));queueIndex=i.getIntExtra("index",0);}if(player!=null)player.release();error="";position=duration=0;state="loading";title=i.getStringExtra("title");track=title;player=new MediaPlayer();player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());player.setDataSource(this,Uri.parse(i.getStringExtra("url")));player.setOnPreparedListener(p->{if(gainFocus()){p.start();state="playing";}else state="paused";session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,title).putLong(MediaMetadata.METADATA_KEY_DURATION,p.getDuration()).build());update();});player.setOnCompletionListener(p->{if(queueIndex+1<queue.length())advance(1);else{state="ended";update();}});player.setOnErrorListener((p,w,e)->{state="error";error="Не удалось воспроизвести источник ("+w+", "+e+")";update();return true;});player.prepareAsync();update();}catch(Exception e){state="error";error=e.getMessage();update();}return START_NOT_STICKY;}
 void advance(int direction){try{int next=queueIndex+direction;if(next<0||next>=queue.length())return;queueIndex=next;JSONObject t=queue.getJSONObject(next);onStartCommand(new Intent(this,MusicService.class).setAction("play").putExtra("url",t.getString("url")).putExtra("title",t.getString("title")),0,0);}catch(Exception e){error=e.getMessage();state="error";update();}}
 void pause(){if(player!=null&&"playing".equals(state)){player.pause();state="paused";update();}}
 void resume(){if(player!=null&&"paused".equals(state)&&gainFocus()){player.start();state="playing";update();}}
 PendingIntent command(String a){return PendingIntent.getService(this,a.hashCode(),new Intent(this,MusicService.class).setAction(a),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 Notification notification(){boolean playing="playing".equals(state);return new Notification.Builder(this,"music").setSmallIcon(R.drawable.icon).setContentTitle(title).setContentText("error".equals(state)?error:"DevLens · "+state).setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1)).addAction(new Notification.Action.Builder(null,playing?"Пауза":"Играть",command(playing?"pause":"resume")).build()).addAction(new Notification.Action.Builder(null,"Стоп",command("stop")).build()).setOngoing(playing).build();}
 void refreshWidgets(){android.appwidget.AppWidgetManager manager=android.appwidget.AppWidgetManager.getInstance(this);new MusicWidget().onUpdate(this,manager,manager.getAppWidgetIds(new ComponentName(this,MusicWidget.class)));}
 void update(){refreshWidgets();int ps="playing".equals(state)?PlaybackState.STATE_PLAYING:"paused".equals(state)?PlaybackState.STATE_PAUSED:PlaybackState.STATE_STOPPED;session.setPlaybackState(new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_SEEK_TO|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS).setState(ps,position,1).build());((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(42,notification());}
 @Override public IBinder onBind(Intent i){return null;}
 @Override public void onDestroy(){handler.removeCallbacksAndMessages(null);unregisterReceiver(noisy);if(player!=null)player.release();if(focus!=null)((AudioManager)getSystemService(AUDIO_SERVICE)).abandonAudioFocusRequest(focus);session.release();state="stopped";refreshWidgets();stopForeground(true);super.onDestroy();}
}
